fn split(s: Str, delimiter: Char) -> Vec<Str> {
    let mut result = vec()
    let mut current = ""
    for c in chars(s) {
        if c == delimiter {
            push(result, current)
            current = ""
        } else {
            current = concat(current, c)
        }
    }
    push(result, current)
    result
}

